import { Client } from '@modelcontextprotocol/sdk/client/index.js';
import { StdioClientTransport } from '@modelcontextprotocol/sdk/client/stdio.js';

const transport = new StdioClientTransport({
  command: '/harness-state/.bun/bin/gbrain',
  args: ['serve', '--surface', 'starter', '--advertise', 'verbs'],
  env: { ...process.env, GBRAIN_HOME: '/harness-state' } as Record<string, string>,
  cwd: '/harness-state',
});
const client = new Client({ name: 'particle-install-check', version: '1.0.0' });
await client.connect(transport);
const tools = (await client.listTools()).tools.map((t) => t.name);
console.log('MCP tools:', tools.join(', '));
const res = await client.callTool({ name: 'recall', arguments: { query: 'install check marker', limit: 5 } });
const text = (res.content as Array<{ type: string; text?: string }>).map((c) => c.text ?? '').join('\n');
console.log('MCP recall isError=', res.isError === true);
console.log(text.slice(0, 1500));
await client.close();

